"""Dashboard local con simulación, configuración y revisión de actividad."""

PAGE = r'''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>mosAIc · Centro de control</title><style>
:root{color-scheme:light;--ink:#20243a;--muted:#767d94;--line:#e6e8f1;--accent:#6955e9;--accent-soft:#efecff;--bg:#f5f6fa;--bad:#b4445a;--ok:#25866d;--nav:#15182d;--amber:#a96a21}
*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,a:focus-visible{outline:3px solid #ada0ff;outline-offset:3px}
.app{min-height:100vh;display:grid;grid-template-columns:220px minmax(0,1fr)}aside.sidebar{background:var(--nav);color:#c5c9de;padding:27px 16px;display:flex;flex-direction:column;gap:30px;position:sticky;top:0;height:100vh}.brand{font-size:27px;letter-spacing:-1.4px;font-weight:800;color:white;padding:0 11px}.brand span{color:#ac9cff}.brand small{display:block;color:#858da9;font-size:11px;font-weight:500;letter-spacing:.7px;margin-top:2px}.nav-label{color:#69738e;text-transform:uppercase;font-size:10px;font-weight:700;letter-spacing:1.4px;padding:0 12px;margin-bottom:10px}nav{display:grid;gap:5px}.nav-button{border:0;background:transparent;color:#aeb5cf;text-align:left;display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:9px;font-size:13px;font-weight:600}.nav-button[aria-selected=true]{background:#6c5be9;color:#fff}.nav-button:hover{background:#292d46}.nav-button[aria-selected=true]:hover{background:#6c5be9}.nav-icon{font-size:17px;width:20px;text-align:center}.count{margin-left:auto;min-width:21px;border-radius:6px;text-align:center;font-size:10px;padding:1px 5px;background:#ffffff16}.sidebar-foot{margin-top:auto;padding:12px;border:1px solid #343850;border-radius:10px;font-size:11px;color:#a6aec9}.sidebar-foot strong{display:block;color:#eeeafa;font-size:12px;margin-bottom:4px}.sidebar-foot p{margin:0}.workspace{min-width:0}.topbar{height:72px;background:white;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 30px;gap:16px}.breadcrumb{font-size:12px;color:var(--muted)}.breadcrumb strong{color:#4c526c;font-weight:600}.top-actions{display:flex;align-items:center;gap:12px}.demo-pill{color:#7c5c18;background:#fff5d9;border:1px solid #f1e2b9;padding:5px 9px;border-radius:6px;font-size:10px;font-weight:750;letter-spacing:.6px}.operator{position:relative}.operator summary{cursor:pointer;font-size:12px;color:#596178;list-style:none;border:1px solid var(--line);padding:7px 11px;border-radius:7px}.operator-box{position:absolute;right:0;top:40px;background:white;border:1px solid var(--line);padding:18px;border-radius:12px;width:320px;z-index:20;box-shadow:0 12px 40px #15182d20}.operator-box p{font-size:12px;color:var(--muted);margin:0 0 8px}.operator-box label{margin-top:8px}
main{padding:28px 30px 55px;max-width:1500px;margin:auto}.page-heading{display:flex;align-items:start;justify-content:space-between;gap:16px;margin-bottom:21px}.eyebrow{text-transform:uppercase;font-size:10px;letter-spacing:1.5px;font-weight:750;color:var(--accent);margin:0 0 6px}h1{font-size:27px;line-height:1.25;letter-spacing:-.8px;margin:0;font-weight:750}.lead{color:var(--muted);margin:7px 0 0;font-size:13px}.scope{font-size:11px;border:1px solid var(--line);background:white;border-radius:7px;padding:7px 10px;color:#747c95;white-space:nowrap}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:24px}.metric{background:#fff;border:1px solid var(--line);border-radius:11px;padding:15px 17px;display:flex;justify-content:space-between;align-items:center}.metric-label{font-size:11px;color:var(--muted);margin:0 0 4px}.metric strong{font-size:25px;line-height:1.2;font-weight:700}.metric-icon{width:32px;height:32px;border-radius:10px;background:#f1efff;display:grid;place-items:center;color:var(--accent);font-size:17px}.metric-icon.red{background:#fff0f2;color:var(--bad)}.metric-icon.amber{background:#fff5e6;color:var(--amber)}
.tab-panel{animation:appear .15s ease}.simulation-toolbar{display:flex;align-items:center;gap:13px;background:white;border:1px solid var(--line);border-radius:11px;padding:12px 16px;margin-bottom:15px;flex-wrap:wrap}.simulation-toolbar label{margin:0;color:var(--muted);font-size:11px}.simulation-toolbar select{width:auto;min-width:150px;font-size:12px}.simulation-toolbar p{color:var(--muted);font-size:11px;margin:0;margin-left:auto}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px;align-items:start}.stack{display:grid;gap:18px}.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:21px;box-shadow:0 2px 8px #181b3603}.card h2{font-size:16px;margin:0;font-weight:700;letter-spacing:-.2px}.card h3{font-size:13px}.desc{color:var(--muted);font-size:12px;margin:5px 0 17px}.section-head{display:flex;align-items:center;gap:10px}.badge{font-size:9px;font-weight:750;letter-spacing:.7px;color:var(--accent);background:#f1eeff;padding:4px 7px;border-radius:5px;margin-left:auto;white-space:nowrap}.simulation-note{display:flex;gap:10px;align-items:start;border:1px solid #e5ddfc;background:#f2effc;color:#716293;padding:11px 14px;border-radius:9px;font-size:11px;margin-bottom:15px}.simulation-note strong{font-weight:650}.step-label{display:flex;align-items:center;gap:7px;font-size:11px;font-weight:650;color:#8b88a6;margin:0 0 11px}.step-label span{background:#eae6fc;border-radius:5px;padding:1px 5px;color:var(--accent)}
label{display:block;font-size:11px;font-weight:650;margin:13px 0 5px;color:#4d536d}input,textarea,select{width:100%;background:#fff;border:1px solid #dde0eb;border-radius:7px;padding:9px 10px;color:var(--ink);font-size:12px}textarea{resize:vertical;min-height:112px;line-height:1.65}textarea.prompt{min-height:320px;font:11px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace}#source-text,#answer{min-height:152px}select[multiple]{min-height:76px}input:focus,textarea:focus,select:focus{outline:2px solid #c4baf7;outline-offset:1px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:15px}button{border:0;border-radius:7px;background:var(--accent);color:white;font-size:11px;font-weight:650;padding:9px 12px}button.secondary{background:#f1effb;color:#6652ac}button.ghost{background:white;border:1px solid var(--line);color:#676e87}.hint{font-size:10.5px;color:var(--muted);margin:8px 0 0;line-height:1.6}.msg{margin-top:12px;padding:10px 12px;border-radius:7px;background:#f1effb;color:#6652ac;font-size:11px;white-space:pre-wrap}.msg.error{background:#fff0f2;color:var(--bad)}.msg:empty{display:none}.output{white-space:pre-wrap;overflow:auto;max-height:260px;background:#f7f8fb;border:1px solid var(--line);border-radius:7px;padding:12px;font:10.5px/1.6 ui-monospace,SFMono-Regular,monospace}.output:empty{display:none}.technical{border-top:1px solid var(--line);margin-top:16px;padding-top:13px}.technical summary{font-size:11px;font-weight:600;cursor:pointer;color:#77718b}hr{border:0;border-top:1px solid var(--line);margin:20px 0}.checklist{display:flex;gap:10px;flex-wrap:wrap}.checklist label{margin:0;display:flex;align-items:center;gap:5px;font-weight:500}.checklist input{width:auto}
.feed-header{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:17px}.feed-header h2{font-size:16px;margin:0}.feed-header p{font-size:11px;margin:3px 0 0;color:var(--muted)}.feed-header select{max-width:190px}.feed{display:grid;gap:10px}.event-row{display:flex;gap:13px;padding:17px;background:#fff;border:1px solid var(--line);border-radius:10px;align-items:start}.event-symbol{width:33px;height:33px;border-radius:10px;background:#fff1f2;color:var(--bad);display:grid;place-items:center;font-weight:800;flex-shrink:0}.event-symbol.flagged{background:#fff5e5;color:var(--amber)}.event-copy{flex:1;min-width:0}.event-copy h3{font-size:12px;font-weight:650;margin:0 0 5px;line-height:1.5}.event-meta{font-size:10px;color:var(--muted);display:flex;gap:8px;flex-wrap:wrap}.event-status{border-radius:4px;padding:1px 5px;background:#f0eff6;color:#746a90;font-size:9px}.event-row button{white-space:nowrap;margin-left:auto}.empty-state{background:#fff;border:1px dashed #d9dcea;border-radius:12px;padding:50px 24px;text-align:center;color:var(--muted)}.empty-state strong{font-size:14px;color:#69718a;display:block;margin-bottom:6px}.empty-state p{font-size:12px;margin:0}.feed-note{color:var(--muted);font-size:11px;margin:12px 0}.global-message{margin-bottom:14px}.toast{position:fixed;right:22px;bottom:22px;max-width:400px;background:#24213e;color:white;padding:15px 17px;border-radius:12px;box-shadow:0 7px 35px #1f203b30;z-index:30;font-size:12px}.toast button{margin-top:9px;background:#514778}
.dialog{width:min(850px,94vw);max-height:90vh;border:1px solid var(--line);border-radius:15px;padding:0;color:var(--ink);box-shadow:0 20px 70px #13152e35}.dialog::backdrop{background:#12152c77}.dialog-head{padding:19px 22px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:16px}.dialog-head h2{font-size:16px;margin:0}.dialog-head button{margin-left:auto}.dialog-body{padding:20px 22px;overflow:auto}.dialog-body h3{font-size:12px;margin:16px 0 6px}.dialog .output{max-height:260px}.private-tag{font-size:10px;color:var(--amber);background:#fff5e4;padding:3px 7px;border-radius:4px}.evidence-summary{font-size:12px;color:#69718a}.log-block{border:1px solid var(--line);padding:12px;border-radius:8px;margin:9px 0}.log-block strong{font-size:11px}.log-block .output{margin:7px 0 0}.risk-entry{font-size:11px;background:#fff2f4;border:1px solid #f1d5db;border-radius:7px;padding:9px;margin:7px 0;color:#a33f54}
@keyframes appear{from{opacity:.7;transform:translateY(3px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){*{animation:none!important}}@media(max-width:1050px){.app{grid-template-columns:185px minmax(0,1fr)}aside.sidebar{padding:23px 10px}.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.simulation-toolbar p{margin-left:0;width:100%}}@media(max-width:650px){.app{display:block}aside.sidebar{height:auto;position:relative;padding:15px;gap:14px}.brand{font-size:23px}.brand small,.nav-label,.sidebar-foot{display:none}nav{display:flex;overflow:auto;gap:5px}.nav-button{padding:9px;white-space:nowrap;font-size:11px}.nav-icon{display:none}.topbar{height:auto;min-height:62px;padding:12px 16px}.top-actions{gap:7px}.breadcrumb{display:none}main{padding:22px 15px}.page-heading{display:block}.scope{display:inline-block;margin-top:10px}.row{grid-template-columns:1fr}.metric{padding:12px}.metric-icon{display:none}.card{padding:17px}.event-row{gap:9px;flex-wrap:wrap}.event-row button{margin-left:42px}.operator-box{right:0;width:min(300px,90vw)}h1{font-size:24px}.feed-header{flex-wrap:wrap}}
</style></head><body>
<div class="app"><aside class="sidebar"><div class="brand">mos<span>AI</span>c<small>AGENT SECURITY WORKSPACE</small></div><div><div class="nav-label">Centro de control</div><nav role="tablist" aria-label="Secciones del dashboard">
<button class="nav-button" id="tab-simulation" role="tab" aria-controls="panel-simulation" aria-selected="true" data-tab="simulation"><span class="nav-icon" aria-hidden="true">↔</span>Simulación</button>
<button class="nav-button" id="tab-settings" role="tab" aria-controls="panel-settings" aria-selected="false" data-tab="settings"><span class="nav-icon" aria-hidden="true">⚙</span>Configuración</button>
<button class="nav-button" id="tab-notifications" role="tab" aria-controls="panel-notifications" aria-selected="false" data-tab="notifications"><span class="nav-icon" aria-hidden="true">◉</span>Notificaciones<span class="count" id="nav-notification-count">0</span></button>
<button class="nav-button" id="tab-flags" role="tab" aria-controls="panel-flags" aria-selected="false" data-tab="flags"><span class="nav-icon" aria-hidden="true">⚑</span>Elementos marcados<span class="count" id="nav-flag-count">0</span></button>
</nav></div><div class="sidebar-foot"><strong>Demo de flujos</strong><p>La evaluación usa mosAIc. Las entradas, salidas y canales se simulan desde este panel.</p></div></aside>
<div class="workspace"><header class="topbar"><div class="breadcrumb">Workspace <span aria-hidden="true">/</span> <strong id="breadcrumb">Simulación</strong></div><div class="top-actions"><span class="demo-pill">DEMO</span><details class="operator"><summary>Acceso de operador</summary><div class="operator-box"><p>El token permite consultar evidencia privada y revisar alertas. Se configura al iniciar la API con MOSAIC_OPERATOR_TOKEN.</p><label for="operator-token">Token de operador</label><input id="operator-token" type="password" autocomplete="off" placeholder="Introduce tu token"><p class="hint">Se mantiene solo en esta página, sin guardarlo.</p></div></details></div></header>
<main><div class="page-heading"><div><p class="eyebrow">Control de divulgaciones</p><h1 id="page-title">Simula el flujo de información</h1><p class="lead" id="page-description">Observa cómo cambia el conocimiento antes de entregar una respuesta.</p></div><div class="scope" id="scope">Cargando workspace…</div></div>
<div class="metrics" aria-label="Actividad registrada"><div class="metric"><div><p class="metric-label">Posibles filtraciones bloqueadas</p><strong id="metric-blocked">0</strong></div><span class="metric-icon red" aria-hidden="true">⊘</span></div><div class="metric"><div><p class="metric-label">Señales marcadas</p><strong id="metric-flagged">0</strong></div><span class="metric-icon amber" aria-hidden="true">⚑</span></div><div class="metric"><div><p class="metric-label">Pendientes de revisión</p><strong id="metric-open">0</strong></div><span class="metric-icon" aria-hidden="true">◷</span></div><div class="metric"><div><p class="metric-label">Secretos configurados</p><strong id="metric-secrets">0</strong></div><span class="metric-icon" aria-hidden="true">◇</span></div></div>
<div id="global-msg" class="msg global-message" role="status"></div>
<section id="panel-simulation" class="tab-panel" role="tabpanel" aria-labelledby="tab-simulation"><div class="simulation-toolbar"><label for="simulation-channel">Escenario</label><select id="simulation-channel"><option value="email">Gestión de correos</option><option value="code">Generación de código</option><option value="document">Generación de informes</option></select><button class="secondary" id="load-example">Cargar ejemplo ficticio</button><p>Los ejemplos solo completan los formularios. El análisis se inicia al pulsar los botones.</p></div><div class="simulation-note"><span aria-hidden="true">ⓘ</span><div><strong>Simulación de entrada y salida.</strong> La evaluación y el registro usan la API de mosAIc. No hay conexión de envío de correo, publicación de código ni aislamiento de procesos.</div></div><div class="grid"><div><p class="step-label"><span>01</span>INFORMACIÓN QUE RECIBE EL AGENTE</p><section class="card"><div class="section-head"><h2>Entrada de información</h2><span class="badge">ONTOLOGÍA</span></div><p class="desc">Simula lo que recibe el agente. Analiza y acepta la evidencia que alimentará su conocimiento.</p>
<label for="source-id">Identificador de fuente</label><input id="source-id" placeholder="ejemplo: correo_01" maxlength="96">
<div class="row"><div><label for="source-day">Fecha</label><input id="source-day" type="date"></div><div><label for="source-users">¿Quién recibió esta fuente?</label><select id="source-users" multiple></select><p class="hint">Opcional. Sin selección, solo se agrega al contexto interno.</p></div></div>
<label for="source-text">Texto de la fuente</label><textarea id="source-text" placeholder="Pega aquí el contenido que conoce el agente…" maxlength="12000"></textarea>
<div class="actions"><button id="preview-source">Analizar fuente</button><button id="accept-source" class="secondary" disabled>Incorporar propuestas</button></div><div class="msg" id="source-msg" role="status"></div><pre class="output" id="source-output"></pre>
</section></div><div><p class="step-label"><span>02</span>RESPUESTA QUE PROPONE EL AGENTE</p><section class="card"><div class="section-head"><h2>Salida del agente</h2><span class="badge">TEXTO LIBRE</span></div><p class="desc">Escribe la respuesta propuesta. mosAIc evalúa el contenido para su destinatario antes de aprobarlo.</p>
<div class="row"><div><label for="review-user">Destinatario</label><select id="review-user"></select></div><div><label for="review-day">Fecha</label><input type="date" id="review-day"></div></div>
<label for="question">Tarea o pregunta</label><input id="question" placeholder="¿Qué necesita saber el destinatario?" maxlength="4000">
<label for="answer">Respuesta del agente</label><textarea id="answer" placeholder="Escribe el borrador que quieres evaluar…" maxlength="4000"></textarea>
<div class="actions"><button id="check-answer">Evaluar respuesta</button><button class="secondary" id="revise-answer" disabled>Evaluar reformulación</button><button class="secondary" id="deliver-answer" disabled>Confirmar entrega</button></div>
<p class="hint">Para reformular, edita el borrador y vuelve a evaluarlo. Solo una respuesta aprobada puede entregarse.</p><div class="msg" id="review-msg" role="status"></div><pre class="output" id="inbox"></pre>
<details class="technical"><summary>Evidencia de esta evaluación</summary><p class="hint">Usa el acceso de operador de la cabecera para ver el detalle privado.</p><div class="actions"><button class="secondary" id="view-trace">Consultar análisis</button></div><div class="msg" id="trace-msg" role="status"></div><pre class="output" id="trace"></pre></details></section></div></div></section>
<section id="panel-settings" class="tab-panel" role="tabpanel" aria-labelledby="tab-settings" hidden><div class="grid"><section class="card"><div class="section-head"><h2>Agentes y prompts</h2><span class="badge">4 AGENTES</span></div><p class="desc">Edita las instrucciones que usan los agentes en la API local.</p>
<label for="agent">Agente</label><select id="agent"><option value="ontology">Constructor de ontología</option><option value="adversary">Analista adversarial</option><option value="analyst">Analista de respuestas</option><option value="rewriter">Reformulador de catálogo</option></select>
<p class="hint" id="agent-help"></p><p class="hint" id="agent-secrets"></p><label for="prompt">Instrucciones del agente</label><textarea id="prompt" class="prompt" spellcheck="false"></textarea>
<div class="actions"><button id="save-prompt">Guardar prompt</button><button class="secondary" id="restore-prompt">Restaurar valor inicial</button></div><div class="msg" id="prompt-msg" role="status"></div>
<p class="hint">La política de secretos se entrega como contexto a los agentes de análisis. El reformulador de catálogo recibe una alternativa ya aprobada; el motor vuelve a validarla.</p></section><section class="card"><div class="section-head"><h2>Secretos y acceso</h2><span class="badge">POLÍTICA</span></div><p class="desc">Define conclusiones protegidas. Los roles elegidos pueden recibirlas; las reglas y los datos siguen siendo parte del grafo.</p><p class="hint" id="empty-secrets"></p>
<label for="secret-select">Conclusión protegida</label><select id="secret-select"></select>
<label for="secret-id">Identificador</label><input id="secret-id" placeholder="ejemplo: contrato_firmado" pattern="[a-z][a-z0-9_]*" maxlength="96">
<label for="secret-desc">¿Qué conocimiento es sensible?</label><textarea id="secret-desc" placeholder="Describe la conclusión que se debe proteger…" maxlength="2000"></textarea>
<label for="secret-mode">¿Qué valores se protegen?</label><select id="secret-mode"><option value="any">Cualquier valor</option><option value="listed">Solo valores específicos</option></select>
<p class="hint">«Cualquier valor» sirve para domicilios, votos u otros datos que no quieres enumerar. Se protege cada valor que el sistema logre representar.</p>
<div id="status-fields" hidden><label for="secret-status">Valores específicos</label><input id="secret-status" placeholder="signed, unsigned"><p class="hint">Identificadores separados por comas, en minúsculas y sin espacios.</p></div>
<div class="row"><div><label for="absolute">Umbral absoluto</label><input id="absolute" type="number" min="0" max="1" step="0.05" value="0.75"></div><div><label for="increase">Umbral de aumento</label><input id="increase" type="number" min="0" max="1" step="0.05" value="0.45"></div></div>
<label>Roles con permiso directo para esta conclusión</label><div class="checklist" id="roles"></div><p class="hint">Los roles también pueden heredar permisos de sus roles superiores.</p>
<div class="actions"><button id="save-secret">Guardar secreto</button><button class="secondary" id="new-secret">Nuevo secreto</button></div><div class="msg" id="secret-msg" role="status"></div>
<p class="hint">Los umbrales no están calibrados. Puedes ampliar la protección, pero el panel no permite eliminar valores protegidos existentes. La cobertura depende de la extracción y las fuentes disponibles.</p>
<hr><h2>Conceptos y relaciones</h2><p class="desc">Agrega los predicados que usarán las reglas intermedias de la ontología.</p>
<label for="vocab-name">Identificador del concepto</label><input id="vocab-name" placeholder="ejemplo: documento_firmado" maxlength="96">
<label for="vocab-desc">Significado</label><input id="vocab-desc" placeholder="Describe cuándo corresponde este concepto" maxlength="2000">
<div class="actions"><button class="secondary" id="save-vocab">Guardar concepto</button></div><p class="hint" id="vocab-list"></p><div class="msg" id="vocab-msg" role="status"></div></section></div></section>
<section id="panel-notifications" class="tab-panel" role="tabpanel" aria-labelledby="tab-notifications" hidden><div class="feed-header"><div><h2>Actividad y notificaciones</h2><p>Bloqueos y señales de las evaluaciones registradas. Sin alertas de ejemplo precargadas.</p></div><button class="ghost refresh-events">Actualizar</button></div><div class="feed" id="notification-feed"></div><p class="feed-note" id="feed-note"></p></section>
<section id="panel-flags" class="tab-panel" role="tabpanel" aria-labelledby="tab-flags" hidden><div class="feed-header"><div><h2>Elementos que necesitan atención</h2><p>Revisar una alerta actualiza su estado; no autoriza una entrega bloqueada.</p></div><select id="flag-filter" aria-label="Filtrar elementos marcados"><option value="open">Pendientes</option><option value="resolved">Revisados</option><option value="dismissed">Descartados</option><option value="all">Todos</option></select></div><div class="feed" id="flag-feed"></div></section>
</main></div></div>
<dialog class="dialog" id="event-dialog" aria-labelledby="event-title"><div class="dialog-head"><div><span class="private-tag">EVIDENCIA PRIVADA</span><h2 id="event-title">Detalle de evaluación</h2></div><button class="ghost" id="close-event">Cerrar</button></div><div class="dialog-body"><p id="event-meta" class="evidence-summary"></p><div id="event-evidence"></div><details class="technical"><summary>Registro estructurado completo</summary><pre class="output" id="event-json"></pre></details><hr><label for="resolution-note">Nota de revisión</label><textarea id="resolution-note" maxlength="1000" placeholder="Añade contexto para el equipo…"></textarea><div class="actions"><button id="resolve-event">Marcar como revisado</button><button class="secondary" id="dismiss-event">Descartar alerta</button></div><div class="msg" id="event-msg" role="status"></div><p class="hint">Este registro contiene salidas estructuradas, evidencias y decisiones. No expone razonamiento interno del proveedor.</p></div></dialog>
<div class="toast" id="event-toast" role="status" hidden><div id="toast-text"></div><button id="toast-open">Ver notificaciones</button></div><script>
const $ = id => document.getElementById(id);
let config = null, activeAgent = 'ontology', sourcePreview = null, review = null;
const agentHelp = {ontology:'Extrae hechos y propone reglas desde las fuentes internas.', adversary:'Explora qué podría inferir un destinatario con su historial.', analyst:'Representa el borrador en el vocabulario y verifica si responde a la tarea.', rewriter:'Reformula hacia una alternativa del catálogo para el endpoint automático.'};
function message(id, text, error=false){const node=$(id);node.textContent=text;node.className='msg'+(error?' error':'')}
function options(id, values){const el=$(id);el.replaceChildren();for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;el.append(option)}}
async function request(url, method='GET', body){const r=await fetch(url,{method,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await r.json()}catch{throw new Error('Respuesta inesperada del servidor')};if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:'Revisa los datos ingresados');if(method!=='GET')setTimeout(()=>refreshFeed().catch(()=>{}),0);return data}
function uid(prefix){return prefix+'_'+crypto.randomUUID().replaceAll('-','')}
function agentView(){activeAgent=$('agent').value;$('prompt').value=config.prompts[activeAgent];$('agent-help').textContent=agentHelp[activeAgent];const families=Object.entries(config.families);$('agent-secrets').textContent=activeAgent==='rewriter'?'Este agente recibe una alternativa ya aprobada, no la lista de secretos.':families.length?'Secretos definidos en la política: '+families.map(([id,f])=>id+' ('+f.description+')').join('; '):'Aún no hay secretos configurados.';message('prompt-msg','')}
function renderRoles(selected=[]){const box=$('roles');box.replaceChildren();for(const role of config.roles){const label=document.createElement('label'),cb=document.createElement('input');cb.type='checkbox';cb.value=role;cb.checked=selected.includes(role);label.append(cb,document.createTextNode(role));box.append(label)}}
function secretMode(){ $('status-fields').hidden=$('secret-mode').value==='any' }
function secretView(){const name=$('secret-select').value;const family=config.families[name];$('secret-id').value=name||'';$('secret-id').readOnly=!!family;$('secret-desc').value=family?.description||'';$('secret-mode').value=(family?.any_value??true)?'any':'listed';$('secret-status').value=family?.statuses.join(', ')||'';secretMode();$('absolute').value=family?.absolute??.75;$('increase').value=family?.increase??.45;renderRoles(Object.keys(config.grants).filter(r=>config.grants[r].includes(name)))}
async function loadConfig(){config=await request('/v1/demo/config');$('scope').textContent=config.scope.org+' / '+config.scope.operation;options('review-user',config.users);options('source-users',config.users);options('secret-select',Object.keys(config.families));$('empty-secrets').textContent=Object.keys(config.families).length?'':'Aún no hay secretos específicos. El analista adversarial evaluará posibles datos sensibles.';$('source-day').value=config.day;$('review-day').value=config.day;$('vocab-list').textContent='Disponibles: '+Object.keys(config.vocabulary).join(', ');agentView();secretView();updateMetrics()}
$('agent').addEventListener('change',agentView);$('secret-select').addEventListener('change',secretView);$('secret-mode').addEventListener('change',secretMode);
$('save-prompt').onclick=async()=>{try{await request('/v1/demo/prompts/'+encodeURIComponent(activeAgent),'PUT',{prompt:$('prompt').value});config.prompts[activeAgent]=$('prompt').value;message('prompt-msg','Prompt guardado. Las revisiones anteriores deberán comprobarse de nuevo.')}catch(e){message('prompt-msg',e.message,true)}};
$('restore-prompt').onclick=()=>{if(config){$('prompt').value=config.default_prompts[activeAgent];message('prompt-msg','Valor inicial restaurado en el editor. Guarda para aplicarlo.')}};
$('new-secret').onclick=()=>{$('secret-select').selectedIndex=-1;secretView();$('secret-id').focus()};
$('save-secret').onclick=async()=>{try{const name=$('secret-id').value.trim(),any_value=$('secret-mode').value==='any';const payload={description:$('secret-desc').value,any_value,statuses:any_value?[]:$('secret-status').value.split(',').map(s=>s.trim()).filter(Boolean),absolute:Number($('absolute').value),increase:Number($('increase').value),allowed_roles:[...$('roles').querySelectorAll('input:checked')].map(e=>e.value)};await request('/v1/demo/secrets/'+encodeURIComponent(name),'PUT',payload);const savedName=name;await loadConfig();$('secret-select').value=savedName;secretView();message('secret-msg','Secreto y permisos guardados.')}catch(e){message('secret-msg',e.message,true)}};
$('save-vocab').onclick=async()=>{try{const name=$('vocab-name').value.trim(),description=$('vocab-desc').value;await request('/v1/demo/vocabulary/'+encodeURIComponent(name),'PUT',{description});config.vocabulary[name]=description;$('vocab-list').textContent='Disponibles: '+Object.keys(config.vocabulary).join(', ');message('vocab-msg','Concepto guardado.')}catch(e){message('vocab-msg',e.message,true)}};
function sourceBody(){return {origin:$('source-id').value.trim(),at:$('source-day').value,text:$('source-text').value,recipients:[...$('source-users').selectedOptions].map(o=>o.value)}}
function invalidateSource(){sourcePreview=null;$('accept-source').disabled=true}$('source-id').oninput=invalidateSource;$('source-text').oninput=invalidateSource;$('source-day').onchange=invalidateSource;$('source-users').onchange=invalidateSource;
$('preview-source').onclick=async()=>{invalidateSource();try{message('source-msg','Analizando fuente con Claude…');const body=sourceBody();const data=await request('/v1/demo/sources/preview','POST',body);if(JSON.stringify(body)!==JSON.stringify(sourceBody())){message('source-msg','La fuente cambió durante el análisis; vuelve a analizarla.',true);return}sourcePreview=data.preview_id;$('source-output').textContent=JSON.stringify(data.observations,null,2);$('accept-source').disabled=!sourcePreview;message('source-msg',sourcePreview?data.observations.length+' propuestas. Revisa el detalle antes de incorporar.':(data.message||'No se extrajeron hechos. La fuente no se incorporó.'),!sourcePreview)}catch(e){message('source-msg',e.message,true)}};
$('accept-source').onclick=async()=>{try{const data=await request('/v1/demo/sources/'+encodeURIComponent(sourcePreview)+'/accept','POST');invalidateSource();message('source-msg',data.accepted?'Propuestas incorporadas al historial.':'Esta fuente ya estaba incorporada.')}catch(e){message('source-msg',e.message,true)}};
function reviewButtons(status){$('revise-answer').disabled=status!=='revise'&&status!=='review';$('deliver-answer').disabled=status!=='approved'}
$('check-answer').onclick=async()=>{try{review=null;reviewButtons('');message('review-msg','Evaluando con Claude y el motor de inferencia…');const user=$('review-user').value,question=$('question').value,day=$('review-day').value,text=$('answer').value;const data=await request('/v1/reviews','POST',{review_id:uid('review'),user,task:'freeform',question,text,day});review={id:data.review_id,user,question,day,text};reviewButtons(data.status);message('review-msg',data.status==='approved'?'Aprobada para entrega.':'Necesita reformulación. '+(data.feedback||''))}catch(e){message('review-msg',e.message,true)}};
function sameTask(){return review&&$('review-user').value===review.user&&$('question').value===review.question&&$('review-day').value===review.day}
$('revise-answer').onclick=async()=>{if(!review)return;if(!sameTask()){message('review-msg','La tarea, fecha o destinatario cambió. Inicia una evaluación nueva.',true);return}try{message('review-msg','Evaluando reformulación…');const text=$('answer').value;const data=await request('/v1/reviews/'+encodeURIComponent(review.id)+'/revisions','POST',{revision_id:uid('revision'),user:review.user,text});review.text=text;reviewButtons(data.status);message('review-msg',data.status==='approved'?'Reformulación aprobada para entrega.':'Necesita otra reformulación. '+(data.feedback||''))}catch(e){message('review-msg',e.message,true)}};
$('deliver-answer').onclick=async()=>{if(!review)return;if(!sameTask()||$('answer').value!==review.text){message('review-msg','El texto, tarea, fecha o destinatario cambió. Evalúa de nuevo antes de entregar.',true);return}try{const data=await request('/v1/reviews/'+encodeURIComponent(review.id)+'/deliver','POST',{user:review.user});reviewButtons('');message('review-msg',data.text?'Entregado: '+data.text:'No se entregó: '+(data.reason||'requiere revisión'));const inbox=await request('/v1/inbox/'+encodeURIComponent(review.user));$('inbox').textContent='Bandeja de '+review.user+'\n'+(inbox.messages.map(m=>m.text).join('\n')||'Sin entregas.')}catch(e){message('review-msg',e.message,true)}};
$('view-trace').onclick=async()=>{if(!review){message('trace-msg','Primero evalúa una respuesta.',true);return}try{const token=$('operator-token').value;const response=await fetch('/v1/reviews/'+encodeURIComponent(review.id)+'?user='+encodeURIComponent(review.user),{headers:{'X-Mosaic-Operator-Token':token}});const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'No se pudo consultar el detalle');$('trace').textContent=JSON.stringify(data.trace,null,2);message('trace-msg','Detalle privado de la evaluación.')}catch(e){message('trace-msg',e.message,true)}};


let activity={events:[],counts:{total:0,blocked:0,flagged:0,open:0}},selectedEvent=null,feedReady=false;
const tabLabels={simulation:['Simula el flujo de información','Observa cómo cambia el conocimiento antes de entregar una respuesta.'],settings:['Configura tus agentes','Ajusta prompts, conclusiones protegidas y permisos del workspace.'],notifications:['Notificaciones','Consulta las evaluaciones que requieren atención.'],flags:['Elementos marcados','Revisa la evidencia y deja constancia de tu decisión.']};
const tabs=[...document.querySelectorAll('[data-tab]')];
function showTab(name){if(!tabLabels[name])name='simulation';for(const tab of tabs){const active=tab.dataset.tab===name;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;$('panel-'+tab.dataset.tab).hidden=!active}$('page-title').textContent=tabLabels[name][0];$('page-description').textContent=tabLabels[name][1];$('breadcrumb').textContent=({simulation:'Simulación',settings:'Configuración',notifications:'Notificaciones',flags:'Elementos marcados'})[name];if(location.hash!=='#'+name)history.replaceState(null,'','#'+name);if(name==='notifications'||name==='flags')refreshFeed().catch(e=>message('global-msg',e.message,true));$('event-toast').hidden=true}
for(const tab of tabs){tab.onclick=()=>showTab(tab.dataset.tab);tab.onkeydown=e=>{if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const direction=['ArrowDown','ArrowRight'].includes(e.key)?1:-1;const next=tabs[(tabs.indexOf(tab)+direction+tabs.length)%tabs.length];showTab(next.dataset.tab);next.focus()}}
window.addEventListener('hashchange',()=>showTab(location.hash.slice(1)));
function updateMetrics(){for(const key of ['blocked','flagged','open'])$('metric-'+key).textContent=String(activity.counts[key]||0);$('metric-secrets').textContent=String(Object.keys(config?.families||{}).length);$('nav-notification-count').textContent=String(activity.counts.total||0);$('nav-flag-count').textContent=String(activity.counts.open||0)}
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el}
function when(value){try{return new Intl.DateTimeFormat('es-CL',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}catch{return value}}
function emptyFeed(box,title,text){box.replaceChildren();const el=node('div',undefined,'empty-state');el.append(node('strong',title),node('p',text));box.append(el)}
function renderFeed(box,items){box.replaceChildren();for(const event of items){const row=node('article',undefined,'event-row'),icon=node('div',event.kind==='blocked'?'⊘':'⚑','event-symbol '+event.kind),copy=node('div',undefined,'event-copy');const meta=node('div',undefined,'event-meta');meta.append(node('span',when(event.created_at)),node('span',event.target_type==='source'?'Análisis de entrada':event.target_type==='delivery'?'Entrega local':'Evaluación de salida'));meta.append(node('span',({open:'Pendiente',resolved:'Revisado',dismissed:'Descartado'})[event.status]||event.status,'event-status'));copy.append(node('h3',event.title),meta);const button=node('button','Ver evidencia','secondary');button.onclick=()=>openEvent(event.id);row.append(icon,copy,button);box.append(row)}}
function renderActivity(){const all=activity.events;const notices=$('notification-feed');if(all.length)renderFeed(notices,all);else emptyFeed(notices,'Todavía no hay notificaciones','Evalúa una entrada o salida para empezar a registrar actividad.');const filter=$('flag-filter').value;const flags=all.filter(e=>filter==='all'||e.status===filter);if(flags.length)renderFeed($('flag-feed'),flags);else emptyFeed($('flag-feed'),'No hay elementos en esta vista','Los bloqueos y señales para revisar aparecerán aquí.');$('feed-note').textContent=all.length?'Mostrando las últimas '+all.length+' notificaciones registradas. Los detalles requieren acceso de operador.':''}
async function refreshFeed(){const previous=new Set(activity.events.map(e=>e.id));const data=await request('/v1/demo/events?limit=100');const newBlocked=data.events.find(e=>e.kind==='blocked'&&!previous.has(e.id));activity=data;updateMetrics();renderActivity();if(feedReady&&newBlocked&&location.hash!=='#notifications'){$('toast-text').textContent=newBlocked.title;$('event-toast').hidden=false}feedReady=true}
$('flag-filter').onchange=renderActivity;for(const button of document.querySelectorAll('.refresh-events'))button.onclick=()=>refreshFeed().catch(e=>message('global-msg',e.message,true));$('toast-open').onclick=()=>showTab('notifications');
async function operatorRequest(path,method='GET',body){const token=$('operator-token').value;if(!token)throw new Error('Introduce el token en «Acceso de operador» para consultar o revisar evidencia privada.');const r=await fetch(path,{method,headers:{'X-Mosaic-Operator-Token':token,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:'No se pudo consultar el registro');return data}
function drawEvent(data){selectedEvent=data;$('event-title').textContent=data.title;$('event-meta').textContent=when(data.created_at)+' · '+(({open:'Pendiente',resolved:'Revisado',dismissed:'Descartado'})[data.status]||data.status);const box=$('event-evidence');box.replaceChildren();const details=data.details;if(details.candidate){box.append(node('h3','Respuesta evaluada'));box.append(node('p',details.candidate,'evidence-summary'))}if(details.recipient)box.append(node('p','Destinatario: '+details.recipient,'hint'));for(const attempt of details.decision?.attempts||[]){for(const risk of attempt.blocked||[]){box.append(node('div',risk.family+' · '+risk.status+' · '+(risk.before*100).toFixed(1)+' % → '+(risk.after*100).toFixed(1)+' %','risk-entry'))}if(attempt.reason)box.append(node('p','Motivo registrado: '+attempt.reason,'hint'))}for(const log of details.logs||[]){const item=node('div',undefined,'log-block');item.append(node('strong',log.agent||log.component),node('pre',JSON.stringify(log.output,null,2),'output'));box.append(item)}if(details.observations){box.append(node('h3','Propuestas de la fuente'));box.append(node('pre',JSON.stringify(details.observations,null,2),'output'))}if(details.notice)box.append(node('p',details.notice,'hint'));$('event-json').textContent=JSON.stringify(data,null,2);$('resolution-note').value=data.resolution_note||'';$('resolution-note').disabled=data.status!=='open';$('resolve-event').disabled=data.status!=='open';$('dismiss-event').disabled=data.status!=='open';message('event-msg','')}
async function openEvent(id){try{const data=await operatorRequest('/v1/demo/events/'+encodeURIComponent(id));drawEvent(data);$('event-dialog').showModal()}catch(e){message('global-msg',e.message,true);document.querySelector('.operator').open=true;$('operator-token').focus()}}
$('close-event').onclick=()=>$('event-dialog').close();
async function resolveEvent(status){if(!selectedEvent)return;try{const data=await operatorRequest('/v1/demo/events/'+encodeURIComponent(selectedEvent.id)+'/resolution','POST',{status,note:$('resolution-note').value});drawEvent(data);await refreshFeed();message('event-msg','Revisión registrada. Esto no autoriza ni entrega el contenido bloqueado.')}catch(e){message('event-msg',e.message,true)}}
$('resolve-event').onclick=()=>resolveEvent('resolved');$('dismiss-event').onclick=()=>resolveEvent('dismissed');
const examples={email:{source:'La persona ficticia Alba escribe: mi dirección es Avenida de Ejemplo 123. Es información privada.',question:'Prepara una respuesta para un tercero.',answer:'La dirección de Alba es Avenida de Ejemplo 123.'},code:{source:'En un proyecto ficticio, la variable TOKEN_INTERNO contiene DEMO_TOKEN_NO_VALIDO_123. Se usa como credencial privada; no debe publicarse.',question:'Explica cómo configurar el proyecto sin revelar credenciales.',answer:'Para configurar el proyecto, utiliza TOKEN_INTERNO=DEMO_TOKEN_NO_VALIDO_123.'},document:{source:'Documento ficticio de personal: Alba tiene un diagnóstico médico reservado. El informe puede decir que la revisión del equipo terminó el viernes.',question:'Redacta un resumen del avance para compartir.',answer:'La revisión terminó el viernes. Alba tiene un diagnóstico médico reservado.'}};
$('load-example').onclick=()=>{const scenario=examples[$('simulation-channel').value];$('source-id').value=uid('fuente_demo');$('source-text').value=scenario.source;for(const option of $('source-users').options)option.selected=false;$('question').value=scenario.question;$('answer').value=scenario.answer;review=null;reviewButtons('');invalidateSource();$('source-output').textContent='';message('source-msg','Ejemplo ficticio cargado. Analiza e incorpora la entrada antes de evaluar la salida.');message('review-msg','');showTab('simulation')};
(async()=>{showTab(location.hash.slice(1));await loadConfig();await refreshFeed()})().catch(e=>message('global-msg','No se pudo cargar el panel: '+e.message,true));
setInterval(()=>{if(!document.hidden)refreshFeed().catch(()=>{})},15000);
</script></body></html>'''
